  let plan; try { plan = await lib.scan(files, p => msg.textContent = 'Scanning ' + p.name + '…'); } catch (e) { body.innerHTML = ''; body.append(h('p', { class: 'bad', text: e.message }), h('button', { class: 'btn', text: 'Back', onclick: openImport })); return; }
